graphql.query:
query Rank($input: RankingInput!) {
  activityRankings(input: $input) {
    __typename
    ... on ActivityRankings {
      location { name region country countryCode elevation timezone }
      forecastFetchedAt
      isStale
      warnings
      activities {
        rank
        activity
        weeklyScore
        weeklyRating
        applicable
        bestDay
        days { date score rating reasons }
      }
    }
    ... on LocationNotFound { message query }
  }
}

query Summary($input: RankingInput!) {
  activityRankings(input: $input) {
    __typename
    ... on ActivityRankings {
      location { name country }
      activities { rank activity weeklyRating bestDay }
    }
  }
}

